// HasTransaction applies the HasEdge predicate on the "transaction" edge.
func HasTransaction() predicate.StablecoinWithdrawal {
	return predicate.StablecoinWithdrawal(func(s *sql.Selector) {
		step := sqlgraph.NewStep(
			sqlgraph.From(Table, FieldID),
			sqlgraph.Edge(sqlgraph.O2O, true, TransactionTable, TransactionColumn),
		)
		sqlgraph.HasNeighbors(s, step)
	})
}

// HasTransactionWith applies the HasEdge predicate on the "transaction" edge with a given conditions (other predicates).
func HasTransactionWith(preds ...predicate.Transaction) predicate.StablecoinWithdrawal {
	return predicate.StablecoinWithdrawal(func(s *sql.Selector) {
		step := newTransactionStep()
		sqlgraph.HasNeighborsWith(s, step, func(s *sql.Selector) {
			for _, p := range preds {
				p(s)
			}
		})
	})
}

// And groups predicates with the AND operator between them.
func And(predicates ...predicate.StablecoinWithdrawal) predicate.StablecoinWithdrawal {
	return predicate.StablecoinWithdrawal(sql.AndPredicates(predicates...))
}

// Or groups predicates with the OR operator between them.
func Or(predicates ...predicate.StablecoinWithdrawal) predicate.StablecoinWithdrawal {
	return predicate.StablecoinWithdrawal(sql.OrPredicates(predicates...))
}

// Not applies the not operator on the given predicate.
func Not(p predicate.StablecoinWithdrawal) predicate.StablecoinWithdrawal {
	return predicate.StablecoinWithdrawal(sql.NotPredicates(p))
}
